import { app, page, route } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };

export default app({
  name: "kanban",
  wasp: { version: "^0.25.0" },
  title: "kanban",
  head: ["<link rel='icon' href='/favicon.ico' />"],
  spec: [
    route("RootRoute", "/", page(MainPage)),
  ],
});

datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

export { ref } from "../refObject.js";
export { WaspSpecUserError } from "../waspSpecUserError.js";
export { action, api, apiNamespace, app, crud, job, page, query, route, } from "./constructors.js";
export type { ActionConfig, ApiConfig, ApiNamespaceConfig, AppConfig, JobConfig, PageConfig, QueryConfig, RouteConfig, } from "./constructors.js";
export type { Register } from "./register.js";
export type * from "./waspSpec.js";
